input.command:
cd /tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/28027b74-c04d-4edd-968a-fd36143955ac/scratchpad && cat > kubiak.py <<'E'
import re,random,sys
from common import *
P='/home/jess/Documents/primary_juvenile_meta-analysis/data/papers_test/md_agents/Kubiak Cunn 2009.md'
FN='Kubiak Cunn 2009'
SRC='Kubiak PJ (2009) Fire responses of bushland plants after the January 1994 wildfires in northern Sydney. Cunninghamia 11(1), 131-165.'
L=open(P).read().split('\n')
brk=[i for i,l in enumerate(L) if l.strip()=='<!-- PAGE BREAK -->']
def page(i): return 130+1+sum(1 for b in brk if b<i)
def fmt(x):
    s=f'{x:.3f}'.rstrip('0').rstrip('.'); return s
def clean(s):
    return re.sub(r'\s+',' ',s.replace('<u>','').replace('</u>','').replace('**',' ')).strip()
def parse_time(cell):
    """return (value, unit, flags) or None"""
    s=clean(cell)
    if not re.search(r'\d',s): return None
    m=re.match(r'^At least (\d+(?:\.\d+)?) years?',s)
    if m: return ('>'+m.group(1),'y',{'plain':False})
    m=re.match(r'^Less than (\d+(?:\.\d+)?) years?',s)
    if m: return ('<'+m.group(1),'y',{'plain':False})
    marks=bool(re.search(r'\?|c\.',s))
    t=s.replace('?','').replace('c.','').replace(' ','')
    m=re.match(r'^(\d+(?:\.\d+)?)(\+)?(?:[–-](\d+(?:\.\d+)?)(\+)?)?',t)
    if not m: return None
    um=re.search(r'\d\+?([wy])(?![a-z])',t) or re.search(r'\d[a-z]*,?\d*\+?([wy])(?![a-z])',t)
    if not um: return None
    unit=um.group(1)
    if m.group(3): val=m.group(1)+'-'+m.group(3)
    elif m.group(2): val='>'+m.group(1)
    else: val=m.group(1)
    plain=bool(re.fullmatch(r'\d+(?:\.\d+)?[wy]',t))
    return (val,unit,{'plain':plain,'marks':marks})
def conv(val,unit):
    if unit=='y': return val
    return re.sub(r'\d+(?:\.\d+)?',lambda m:fmt(float(m.group())/52),val)
CODEDEF={'r':'a small proportion of adult plants resprouted','k':'a small proportion of adult plants were killed','pR':'probably resprouted','pK':'probably killed','?R':'possibly resprouted','?K':'possibly killed'}
def resp(cell):
    raw=cell.strip(); note=''
    if raw.startswith('R(1)m.i.f'): return 'R(1)','LCR printed: '+raw+' (m.i.f = moderate intensity fire; (1) = one plant).'
    if raw.startswith('K;r'): return 'K;r','Printed: '+raw+' (m.i.f = moderate intensity fire).'
    if not raw or not re.fullmatch(r'[?pPKkRr/; ]+',raw): return '','Printed comment: '+raw if raw else ''
    code=raw.replace(' ','')
    if code=='R': return 'resprouter',''
    if code=='K': return 'obligate',''
    d='; '.join(f'{k} = {v}' for k,v in CODEDEF.items() if k in re.split(r'[/;]',code))
    return code,('Fire response code printed as in paper'+(f' ({d})' if d else ' (mixed or uncertain code)')+'.')
rows=[]
for i,ln in enumerate(L):
    if i<450 or not ln.startswith('|'):continue
    c=[x.strip() for x in ln.strip().strip('|').split('|')]
    if c[0]=='Family' or set(c[0])<=set('-'):continue
    assert len(c)==12,ln
    rows.append((i,c))
COLN={'ffr':'Time to first flower production resprout_repr3a','ffs':'Age at first flower production from seed_repr3','pjp':'primary_juvenile_period','sjp':'secondary_juvenile_period'}
out=[];skipped=[];chk=[]
for i,c in rows:
    fam,name,peak,lcr,nl,seedl,ffr,ffs,frr,frs,pjp,sjp=c
    exotic=name.startswith('*') or name.startswith('(*?)')
    exnote=''
    n=name
    if n.startswith('(*?)'): n=n[4:]; exnote='Name printed with (*?) before it: possibly exotic; not marked as introduced.'
    elif n.startswith('*'): n=n[1:]
    genus,rest=n.split(' ',1)
    mm=re.search(r' (subsp\.|var\.|cv\.) ',rest)
    if mm: species=rest[:mm.start()]; subsp=rest[mm.start()+1:]
    else: species=rest; subsp=''
    sci=n
    if exotic and name.startswith('*'):
        if subsp: exnote='Exotic species (* printed before name); subsp column holds the subspecies/variety so * not used there.'
        else: subsp='*'; sci=n+' *'
    pg=page(i)
    sites=[]
    notes_extra=[]
    rc={}
    for key,cell,sname in (('LCR',lcr,'Lane Cove River catchment'),('NL',nl,'Narrabeen Lagoon catchment')):
        code,rn=resp(cell)
        if code:
            sites.append(sname);rc[sname]=(code,rn)
        elif rn: notes_extra.append(f'{key} cell {rn}')
    # times
    tn=[];vals={}
    underl=any('<u>' in x for x in (ffr,ffs))
    for key,cell in (('ffr',ffr),('ffs',ffs),('pjp',pjp),('sjp',sjp)):
        if not cell: continue
        if key in('ffr','ffs') and '<u>' in cell: continue
        r=parse_time(cell)
        if not r:
            tn.append(f'{COLN[key]} cell printed text: {clean(cell)}'); continue
        val,unit,fl=r
        if key=='sjp':
            vals[key]=(val,'weeks' if unit=='w' else 'years')
            tn_extra=''
        else:
            if unit=='w':
                v2=conv(val,unit); vals[key]=(v2,None); tn.append(f'{COLN[key]} converted from {val} weeks')
            else: vals[key]=(val,None)
        if not fl['plain']: tn.append(f'{COLN[key]} printed as \'{clean(cell)}\''+(' (c./? marks removed from value)' if fl.get('marks') else '')+(' (first value used where several given)' if re.search(r'[,&]',clean(cell)) else ''))
    if underl:
        tn.append('First flowering printed underlined (unclear whether from seed or from resprouts): '+clean(ffs or ffr)+'; not entered in either column')
    other=[]
    if seedl: other.append(f'Seedlings first observed: {seedl}')
    if frr and not (frr==frs and '<u>' in frr): other.append('First fruiting (resprouts): '+clean(frr))
    if frs and not (frr==frs and '<u>' in frs): other.append('First fruiting (seed): '+clean(frs))
    if frr and frr==frs and '<u>' in frr: other.append('First fruiting (resprouts/seed, underlined): '+clean(frr))
    if peak: other.append('Post-fire peak as printed: '+peak)
    has_time=bool(vals)
    base=f'Appendix 1, p. {pg}. Wildfire of January 1994; fire season Summer derived from the fire date; fires generally of high intensity but patchy.'
    if exnote: base+=' '+exnote
    base+=' First fruiting, seedling and peak entries are near-matches kept in Notes only.' if other else ''
    cols=dict(Genus=genus,Species=species,subsp=subsp,scientific_name=sci,Family=fam,Fire_type='wildfire',Fire_season_categorical='Summer',Fire_severity_categorical='High',Source=SRC,File_name=FN)
    def timecols(r):
        for key,(v,u) in vals.items():
            r[COLN[key]]=v
            if key=='sjp': r['Time_unit']=u
    made=[]
    if len(sites)==1:
        s=sites[0];code,rn=rc[s]
        r=mk(**{k.replace(' ','__'):v for k,v in cols.items()})
        r['fire_response categorical_surv1']=code;r['Location_name']=s;r['Latitude']='-33.75';r['Longitude']='151.0833'
        timecols(r)
        r['Notes']=' '.join([base,rn]+[x+'.' for x in tn+other+notes_extra]).strip()
        made.append(r)
    elif len(sites)==2:
        for s in sites:
            code,rn=rc[s]
            r=mk(**{k.replace(' ','__'):v for k,v in cols.items()})
            r['fire_response categorical_surv1']=code;r['Location_name']=s;r['Latitude']='-33.75';r['Longitude']='151.0833'
            r['Notes']=' '.join([base,rn]+([x+'.' for x in other+notes_extra] if not has_time else [])+(['Time values not split by site: see separate row for both catchments.'] if has_time else [])).strip()
            made.append(r)
        if has_time:
            r=mk(**{k.replace(' ','__'):v for k,v in cols.items()})
            r['Location_name']='Lane Cove River catchment / Narrabeen Lagoon catchment'
            timecols(r)
            r['Notes']=' '.join([base,'Values not split by site in Appendix 1; species recorded at both catchments.']+[x+'.' for x in tn+other+notes_extra]).strip()
            made.append(r)
    else:
        if has_time:
            r=mk(**{k.replace(' ','__'):v for k,v in cols.items()})
            r['Location_name']='Lane Cove River catchment / Narrabeen Lagoon catchment'
            timecols(r)
            r['Notes']=' '.join([base,'Catchment not stated for this species (LCR and NL columns empty).']+[x+'.' for x in tn+other+notes_extra]).strip()
            made.append(r)
        else: skipped.append(name)
    for r in made: chk.append((L[i],r)); out.append(r)
random.seed(int(sys.argv[1]) if len(sys.argv)>1 else None)
for ln,r in random.sample(chk,3):
    print(ln);print({k:v for k,v in r.items() if v and k not in('Source','File_name','Fire_type','Fire_season_categorical','Fire_severity_categorical','Latitude','Longitude')})
if len(sys.argv)>2 and sys.argv[2]=='write': append(out)
print(len(out),'rows; species with no row:',len(skipped)); print(skipped)
E
python3 kubiak.py

