    if mm: species=rest[:mm.start()]; subsp=rest[mm.start()+1:]
    else: species=rest; subsp=''
    sci=n
    if exotic and name.startswith('*'):
        if subsp: exnote='Exotic species (* printed before name); subsp column holds the subspecies/variety so * not used there.'
        else: subsp='*'; sci=n+' *'
    pg=page(i)
    sites=[]
    notes_extra=[]
    rc={}
    for key,cell,sname in (('LCR',lcr,'Lane Cove River catchment'),('NL',nl,'Narrabeen Lagoon catchment')):
        code,rn=resp(cell)
        if code:
            sites.append(sname);rc[sname]=(code,rn)
        elif rn: notes_extra.append(f'{key} cell {rn}')
    # times
    tn=[];vals={}
    underl=any('<u>' in x for x in (ffr,ffs))
    for key,cell in (('ffr',ffr),('ffs',ffs),('pjp',pjp),('sjp',sjp)):
        if not cell: continue
        if key in('ffr','ffs') and '<u>' in cell: continue
        r=parse_time(cell)
        if not r:
            tn.append(f'{COLN[key]} cell printed text: {clean(cell)}'); continue
        val,unit,fl=r
        if key=='sjp':
            vals[key]=(val,'weeks' if unit=='w' else 'years')
            tn_extra=''
        else:
            if unit=='w':
                v2=conv(val,unit); vals[key]=(v2,None); tn.append(f'{COLN[key]} converted from {val} weeks')
            else: vals[key]=(val,None)
        if not fl['plain']: tn.append(f'{COLN[key]} printed as \'{clean(cell)}\''+(' (c./? marks removed from value)' if fl.get('marks') else '')+(' (first value used where several given)' if re.search(r'[,&]',clean(cell)) else ''))
    if underl:
        tn.append('First flowering printed underlined (unclear whether from seed or from resprouts): '+clean(ffs or ffr)+'; not entered in either column')
    other=[]
    if seedl: other.append(f'Seedlings first observed: {seedl}')
    if frr and not (frr==frs and '<u>' in frr): other.append('First fruiting (resprouts): '+clean(frr))
    if frs and not (frr==frs and '<u>' in frs): other.append('First fruiting (seed): '+clean(frs))
    if frr and frr==frs and '<u>' in frr: other.append('First fruiting (resprouts/seed, underlined): '+clean(frr))
    if peak: other.append('Post-fire peak as printed: '+peak)
    has_time=bool(vals)
    base=f'Appendix 1, p. {pg}. Wildfire of January 1994; fire season Summer derived from the fire date; fires generally of high intensity but patchy.'
    if exnote: base+=' '+exnote
    base+=' First fruiting, seedling and peak entries are near-matches kept in Notes only.' if other else ''
    cols=dict(Genus=genus,Species=species,subsp=subsp,scientific_name=sci,Family=fam,Fire_type='wildfire',Fire_season_categorical='Summer',Fire_severity_categorical='High',Source=SRC,File_name=FN)
    def timecols(r):
        for key,(v,u) in vals.items():
            r[COLN[key]]=v
            if key=='sjp': r['Time_unit']=u
    made=[]
    if len(sites)==1:
        s=sites[0];code,rn=rc[s]
        r=mk(**{k.replace(' ','__'):v for k,v in cols.items()})
        r['fire_response categorical_surv1']=code;r['Location_name']=s;r['Latitude']='-33.75';r['Longitude']='151.0833'
        timecols(r)
        r['Notes']=' '.join([base,rn]+[x+'.' for x in tn+other+notes_extra]).strip()
        made.append(r)
    elif len(sites)==2:
        for s in sites:
            code,rn=rc[s]
            r=mk(**{k.replace(' ','__'):v for k,v in cols.items()})
            r['fire_response categorical_surv1']=code;r['Location_name']=s;r['Latitude']='-33.75';r['Longitude']='151.0833'
            r['Notes']=' '.join([base,rn]+([x+'.' for x in other+notes_extra] if not has_time else [])+(['Time values not split by site: see separate row for both catchments.'] if has_time else [])).strip()
            made.append(r)
        if has_time:
            r=mk(**{k.replace(' ','__'):v for k,v in cols.items()})
            r['Location_name']='Lane Cove River catchment / Narrabeen Lagoon catchment'
            timecols(r)
            r['Notes']=' '.join([base,'Values not split by site in Appendix 1; species recorded at both catchments.']+[x+'.' for x in tn+other+notes_extra]).strip()
            made.append(r)
    else:
        if has_time:
            r=mk(**{k.replace(' ','__'):v for k,v in cols.items()})
            r['Location_name']='Lane Cove River catchment / Narrabeen Lagoon catchment'
            timecols(r)
            r['Notes']=' '.join([base,'Catchment not stated for this species (LCR and NL columns empty).']+[x+'.' for x in tn+other+notes_extra]).strip()
            made.append(r)
        else: skipped.append(name)
    for r in made: chk.append((L[i],r)); out.append(r)
random.seed(int(sys.argv[1]) if len(sys.argv)>1 else None)
for ln,r in random.sample(chk,3):
    print(ln);print({k:v for k,v in r.items() if v and k not in('Source','File_name','Fire_type','Fire_season_categorical','Fire_severity_categorical','Latitude','Longitude')})
if len(sys.argv)>2 and sys.argv[2]=='write': append(out)
print(len(out),'rows; species with no row:',len(skipped)); print(skipped)
